part of 'ephemeris.dart';

// Delta T = TT - UT1 from observed USNO/IERS values (delta_t_table.dart,
// generated by tool/deltat/gen_deltat.py), with smooth extrapolation.
//
// * 1657.0 .. end of table (about one year after the retrieval date; the last
//   13 monthly rows are IERS Bulletin A predictions): C1 piecewise cubic
//   Hermite interpolation of the table.
// * After the table: dT_end + s*d + 32.5*(d/36525)^2 seconds, d = days after
//   the last row, s = 3-year least-squares trend of the table
//   ([deltaTEndSlopePerDay], also the Hermite slope of the last row, so value
//   and slope are continuous). 32.5 s/cy^2 is the curvature of the long-term
//   parabola of Stephenson, Morrison & Hohenkerk (2016), i.e. tidal braking;
//   the decade-scale fluctuations are unpredictable, so no further terms.
// * Before 1657: the Espenak-Meeus polynomial, plus the offset to the first
//   table row fading linearly to zero over one century (continuous).

/// Hermite slopes (seconds per day) for [deltaTTableUt], built on first use.
Float64List? _deltaTSlopes;

Float64List _slopes() {
  final Float64List? cached = _deltaTSlopes;
  if (cached != null) return cached;
  const List<double> x = deltaTTableUt;
  const List<double> y = deltaTTableSeconds;
  final int n = x.length;
  final Float64List m = Float64List(n);
  m[0] = (y[1] - y[0]) / (x[1] - x[0]);
  for (int i = 1; i < n - 1; i++) {
    // Three-point derivative on a non-uniform grid.
    final double h0 = x[i] - x[i - 1];
    final double h1 = x[i + 1] - x[i];
    final double d0 = (y[i] - y[i - 1]) / h0;
    final double d1 = (y[i + 1] - y[i]) / h1;
    m[i] = (d0 * h1 + d1 * h0) / (h0 + h1);
  }
  m[n - 1] = deltaTEndSlopePerDay;
  _deltaTSlopes = m;
  return m;
}

/// Delta T (TT - UT1) in seconds for [ut] = UT days since J2000.
///
/// This is the model installed into Astronomy Engine (`setDeltaTFunction`)
/// by [installEphemerisDeltaT].
double deltaTModelSeconds(double ut) {
  const List<double> x = deltaTTableUt;
  const List<double> y = deltaTTableSeconds;
  final int n = x.length;
  if (ut.isNaN) return double.nan;
  if (ut >= x[n - 1]) {
    final double d = ut - x[n - 1];
    final double c = d / 36525.0;
    return y[n - 1] + deltaTEndSlopePerDay * d + 32.5 * c * c;
  }
  if (ut < x[0]) {
    final double offset = y[0] - ae.deltaTEspenakMeeus(x[0]);
    final double w = 1.0 - (x[0] - ut) / 36525.0;
    return ae.deltaTEspenakMeeus(ut) + (w > 0 ? offset * w : 0.0);
  }
  // Binary search: x[lo] <= ut < x[lo + 1].
  int lo = 0;
  int hi = n - 1;
  while (hi - lo > 1) {
    final int mid = (lo + hi) >> 1;
    if (x[mid] <= ut) {
      lo = mid;
    } else {
      hi = mid;
    }
  }
  final Float64List m = _slopes();
  final double h = x[hi] - x[lo];
  final double s = (ut - x[lo]) / h;
  final double s2 = s * s;
  final double s3 = s2 * s;
  return (2 * s3 - 3 * s2 + 1) * y[lo] +
      (s3 - 2 * s2 + s) * h * m[lo] +
      (-2 * s3 + 3 * s2) * y[hi] +
      (s3 - s2) * h * m[hi];
}

bool _deltaTInstalled = false;

/// Installs [deltaTModelSeconds] as Astronomy Engine's Delta T model (once per
/// isolate). Every public function of this library calls it first; code that
/// builds `AstroTime` objects directly must call it before doing so, because an
/// `AstroTime` keeps the TT it was constructed with.
void installEphemerisDeltaT() {
  if (_deltaTInstalled) return;
  ae.setDeltaTFunction(deltaTModelSeconds);
  _deltaTInstalled = true;
}
